const v = H.plot2d({ xMin: -6, xMax: 6, yMin: -4, yMax: 4 });
v.grid(); v.axes();
const eps0 = 8.854e-12;          // F/m
const A = P.A * 1e-4;            // plate area, cm^2 -> m^2
const d_mm = P.d;               // gap in mm
const d = d_mm * 1e-3;          // gap in metres
const C = eps0 * A / Math.max(1e-9, d); // farads
const C_pF = C * 1e12;
// geometry: plate half-height scales with sqrt(area); gap scales with d_mm
const ph = H.clamp(0.6 * Math.sqrt(P.A), 1.2, 3.4);   // plate half-height (data units)
const gap = H.clamp(d_mm * 0.5, 0.3, 3.2);            // half-gap (data units)
// top (+) plate on the right, bottom (-) plate on the left of the gap
v.rect(gap, -ph, 0.35, 2 * ph, { fill: H.colors.warn, stroke: H.colors.ink, width: 1 });
v.rect(-gap - 0.35, -ph, 0.35, 2 * ph, { fill: H.colors.accent, stroke: H.colors.ink, width: 1 });
v.text("+Q", gap + 0.6, ph + 0.4, { color: H.colors.warn, size: 13, weight: 700 });
v.text("−Q", -gap - 0.95, ph + 0.4, { color: H.colors.accent, size: 13, weight: 700 });
// uniform field lines from + plate to - plate; little charges drift across
// (animated, looping) to show the gap is what's being changed
const nlines = 7;
for (let i = 0; i < nlines; i++) {
  const y = -ph + 2 * ph * (i + 0.5) / nlines;
